// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;

    function setUp() public { c = new ERCDDAToken(0, "", ""); }

    function testFuzz_property(address target, bool freeze) public {
        // Owner of c is this test contract (deployer). Only freeze targets distinct
        // from the owner are admissible: for those, freezing must hit exactly target.
        vm.assume(target != address(this));

        vm.prank(address(this));
        c.freezeAccount(target, freeze);

        // General rule: after freezeAccount(target, freeze) by the owner,
        // frozenAccount(target) == freeze (and the owner is untouched).
        assertTrue(c.frozenAccount(target) == freeze);
    }
}
